-- Seed data para competencias específicas de 6to Grado del Nivel Secundario
-- Documento oficial: Adecuación Curricular Nivel Secundario - Segundo Ciclo (6to Grado)

INSERT INTO public.curr_competencias_especificas (nivel, grado, asignatura, bloque, competencia_fundamental, codigo, descriptor) VALUES
-- Lengua Española
('Secundaria', '6to', 'Lengua Española', 'BC1', 'Comunicativa', 'CE-LE1', 'Exhibe desenvolvimiento y creatividad al comunicarse eficazmente de manera personal y colectiva, utilizando un modelo textual, a partir de la comprensión y producción, con uso ético y responsable de plataformas tecnológicas y diferentes medios y recursos.'),
('Secundaria', '6to', 'Lengua Española', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LE2', 'Expone la validez de informaciones diversas sostenidas en juicios, puntos de vista, conclusiones y acciones, usando un género textual conveniente, respetando las demás opiniones.'),
('Secundaria', '6to', 'Lengua Española', 'BC2', 'Resolución de Problemas', 'CE-LE3', 'Presenta resultados de investigaciones a través de textos convenientes que evidencian soluciones de problemas, tomando en cuenta la audiencia y manifestando postura crítica, valórica y de respeto frente a lo que se lee, escucha y escribe.'),
('Secundaria', '6to', 'Lengua Española', 'BC4', 'Ética y Ciudadana', 'CE-LE4', 'Usa textos de secuencia argumentativa en la elaboración de proyectos como elemento clave, hacia la construcción de una ciudadanía responsable y dinámica que busca solución de problemas colectivos.'),
('Secundaria', '6to', 'Lengua Española', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LE7', 'Canaliza emociones y sentimientos en lecturas y escrituras reflexivas, a través de un tipo de texto conveniente, fortaleciendo las relaciones humanas y el respeto a la dignidad propia y de otras personas.'),
('Secundaria', '6to', 'Lengua Española', 'BC3', 'Científica y Tecnológica', 'CE-LE5', 'Explica resultados de investigaciones que realiza, apoyándose en el uso de textos de secuencia expositivo-explicativa, en actos de intercomunicación que se desarrollan en la escuela y otro contexto, utilizando herramientas tecnológicas y otros recursos.'),
('Secundaria', '6to', 'Lengua Española', 'BC3', 'Ambiental y de la Salud', 'CE-LE6', 'Utiliza sus conocimientos en la promoción y divulgación de comportamientos y valores sobre la conservación de la salud, la naturaleza y sus ecosistemas, mediante el uso de textos y a través de actividades de intercomunicación en diferentes contextos de la comunidad, apoyados en recursos variados, herramientas tecnológicas y otros medios y recursos.'),

-- Lenguas Extranjeras - Inglés
('Secundaria', '6to', 'Inglés', 'BC1', 'Comunicativa', 'CE-LEI1', 'Se comunica en el idioma inglés de forma comprensible y con un discurso sostenido en el que, hipotetiza, compara épocas, justifica su criterio y costumbres y expresa experiencias, en distintas situaciones de comunicación sobre temas cotidianos, culturales o abstractos de su interés.'),
('Secundaria', '6to', 'Inglés', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LEI2', 'Se comunica en el idioma inglés utilizando una estructura lógica y una presentación creativa del discurso para tratar temas abstractos o culturales de su interés, presentando informaciones, experiencias, razonamientos, y justificación de opinión de forma detallada y empleando estrategias de desempeño comunicativo.'),
('Secundaria', '6to', 'Inglés', 'BC2', 'Resolución de Problemas', 'CE-LEI3', 'Describe problemas y situaciones de su entorno inmediato o de temas que le son familiares, planteando razonamientos e hipótesis, puntos de vista y acciones para su solución de forma comprensible, sencilla y detallada en inglés oral y escrito.'),
('Secundaria', '6to', 'Inglés', 'BC4', 'Ética y Ciudadana', 'CE-LEI4', 'Se relaciona con las demás personas con cortesía, respeto y valoración crítica de las diferencias individuales y la identidad social y cultural local y global, al interactuar en el idioma inglés, de forma oral y escrita.'),
('Secundaria', '6to', 'Inglés', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LEI7', 'Se comunica en el idioma inglés, con cortesía, honestidad y actitud de respeto, al compartir informaciones, experiencias y razonamientos y puntos de vista.'),
('Secundaria', '6to', 'Inglés', 'BC3', 'Científica y Tecnológica', 'CE-LEI5', 'Se comunica en el idioma inglés de forma comprensible para expresar razonamientos, explicaciones y justificar sus aseveraciones sobre asuntos científicos y tecnológicos de su utilidad, en distintas situaciones cotidianas de comunicación.'),
('Secundaria', '6to', 'Inglés', 'BC3', 'Ambiental y de la Salud', 'CE-LEI6', 'Justifica acciones y puntos de vista en interacciones sencilla y comprensibles en inglés, ofreciendo información, razonamientos y explicaciones relativas a estilos de vida saludables y cuidado del medioambiente, en distintas situaciones de comunicación.'),

-- Lenguas Extranjeras - Francés
('Secundaria', '6to', 'Francés', 'BC1', 'Comunicativa', 'CE-LEF1', 'Comprende y expresa ideas, sentimientos y valores culturales en distintas situaciones de comunicación, utilizando el idioma francés de forma breve y sencilla con la finalidad de procurar servicio de transporte, informar sobre viajes, relatar experiencias, interactuar en restaurantes y dar y pedir opiniones, en relación a necesidades concretas y temas cotidianos.'),
('Secundaria', '6to', 'Francés', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LEF2', 'Interactúa de forma oral y escrita en el idioma francés, empleando razonamiento lógico-verbal y estrategias de desempeño de manera creativa y crítica en distintas situaciones de comunicación, donde procurar servicio de transporte, informar sobre viajes, relatar experiencias, interactuar en restaurantes y dar y pedir opiniones con expresiones breves y sencillas.'),
('Secundaria', '6to', 'Francés', 'BC2', 'Resolución de Problemas', 'CE-LEF3', 'Interactúa en francés ante diversas situaciones y problemas comunes de su entorno inmediato en las que procura servicio de transporte, informa sobre viajes, relata experiencias, interactúa en restaurantes y da y pide opiniones, empleando estrategias de desempeño oral y escrito para lograr la claridad del mensaje.'),
('Secundaria', '6to', 'Francés', 'BC4', 'Ética y Ciudadana', 'CE-LEF4', 'Se comunica con las demás personas en el idioma francés de forma oral y escrita, con cortesía, honestidad, asertividad y respeto, en intercambios sencillos, siguiendo las normas de convivencia y organización establecidas y reconociendo las diferencias individuales y la identidad social y cultural propias de la comunidad local y global, relativas a transporte público, comidas, bebidas, lugares de interés, costumbres y tradiciones.'),
('Secundaria', '6to', 'Francés', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LEF7', 'Interactúa en el idioma francés con cortesía, honestidad, asertividad, actitud de respeto y aceptación al referirse a sí mismo/a y a las demás personas, al expresar opiniones y relatar experiencias.'),
('Secundaria', '6to', 'Francés', 'BC3', 'Científica y Tecnológica', 'CE-LEF5', 'Se comunica en el idioma francés de forma personal, digital o virtual con el propósito de relatar experiencias, opinar e intercambiar información sobre asuntos científicos, tecnológicos y de otra índole, en distintas situaciones de comunicación.'),
('Secundaria', '6to', 'Francés', 'BC3', 'Ambiental y de la Salud', 'CE-LEF6', 'Muestra preferencia por opciones que impactan positivamente la salud y el medioambiente al informar sobre viajes, procurar servicio de transporte, interactuar en restaurantes y dar y pedir opiniones en diversas situaciones de comunicación en el idioma francés, utilizando frases y oraciones sencillas.'),

-- Matemática
('Secundaria', '6to', 'Matemática', 'BC1', 'Comunicativa', 'CE-MAT1', 'Formula definiciones y expresa generalizaciones resultado de la indagación y la resolución de problemas matemáticos.'),
('Secundaria', '6to', 'Matemática', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-MAT2', 'Construye demostraciones incluyendo aquellas indirectas y usando el principio de inducción, para comprobar teorías y proposiciones matemáticas.'),
('Secundaria', '6to', 'Matemática', 'BC2', 'Resolución de Problemas', 'CE-MAT3', 'Analiza procesos de formulación de modelos matemáticos para resolver situaciones de problemas del mundo real.'),
('Secundaria', '6to', 'Matemática', 'BC4', 'Ética y Ciudadana', 'CE-MAT4', 'Trabaja en equipo, aceptando los argumentos ajenos, en la búsqueda de soluciones a problemas desde la matemática.'),
('Secundaria', '6to', 'Matemática', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-MAT7', 'Muestra autonomía a partir del empleo de estrategias diversas de cálculos matemáticos para dar solución a situaciones que se presentan en la comunidad, respetando el punto de vista de las demás personas.'),
('Secundaria', '6to', 'Matemática', 'BC3', 'Científica y Tecnológica', 'CE-MAT5', 'Evalúa herramientas tecnológicas para la resolución de problemas diversos desde los conocimientos matemáticos, a fin de tomar decisiones en situaciones del contexto.'),
('Secundaria', '6to', 'Matemática', 'BC3', 'Ambiental y de la Salud', 'CE-MAT6', 'Aplica la modelación matemática para la toma de decisiones sobre situaciones que afectan la salud y el medioambiente.'),

-- Ciencias Sociales
('Secundaria', '6to', 'Ciencias Sociales', 'BC1', 'Comunicativa', 'CE-CS1', 'Reconoce en proyectos de investigación el valor de utilizar fuentes primarias y secundarias, con la finalidad presentar argumentos sólidos y confiables sobre hechos sociales, políticos, económicos, históricos, geográficos o cultural.'),
('Secundaria', '6to', 'Ciencias Sociales', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-CS2', 'Compara la relación existente entre los procesos históricos ocurridos en espacios geográficos de la República Dominicana, mediante el uso de hipótesis, con la finalidad presentar argumentaciones que evidencien su influencia en los cambios económicos, sociales, políticos y culturales del contexto en el que se produjeron.'),
('Secundaria', '6to', 'Ciencias Sociales', 'BC2', 'Resolución de Problemas', 'CE-CS3', 'Explica en investigaciones y producciones la existencia de un problema y las diversas situaciones que pueden surgir en torno a él; con la finalidad de comprender sus implicaciones y las posibles soluciones que puedan ser implementadas en función de su contexto.'),
('Secundaria', '6to', 'Ciencias Sociales', 'BC4', 'Ética y Ciudadana', 'CE-CS4', 'Elabora proyectos de investigación que fomenten la promoción de los valores culturales e interculturales, la construcción ciudadana y la convivencia democrática en cualquier espacio, con la finalidad de propiciar el respeto por la Constitución y los derechos humanos.'),
('Secundaria', '6to', 'Ciencias Sociales', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-CS7', 'Ejemplifica relaciones de respeto a su persona y la sociedad; con la finalidad de construir una convivencia armoniosa al tratar a los demás con amabilidad y empatía, escuchar y considerar diferentes puntos de vista, resolver los conflictos de manera pacífica y constructiva, sin discriminación o menosprecio hacia los demás.'),
('Secundaria', '6to', 'Ciencias Sociales', 'BC3', 'Científica y Tecnológica', 'CE-CS5', 'Realiza estudio comparativo de diferentes teorías relacionadas a fenómenos naturales y sociales utilizando la tecnología; con la finalidad de presentar artículos científicos y publicaciones especializadas, así como también datos que apoyen sus conclusiones.'),
('Secundaria', '6to', 'Ciencias Sociales', 'BC3', 'Ambiental y de la Salud', 'CE-CS6', 'Propone actividades que propician el cuidado de su entorno y estilos de vida saludable, con la finalidad de garantizar el cuidado de su salud y del medioambiente.'),

-- Ciencias de la Naturaleza – Física
('Secundaria', '6to', 'Ciencias de la Naturaleza', 'BC1', 'Comunicativa', 'CE-CN1', 'Se comunica utilizando el lenguaje científico y tecnológico fundamental de la física que implica ideas, leyes, modelos y procesos.'),
('Secundaria', '6to', 'Ciencias de la Naturaleza', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-CN2', 'Ofrece explicaciones y estrategias científicas y tecnológicas a problemas y fenómenos naturales relacionados con los fundamentos de la Física.'),
('Secundaria', '6to', 'Ciencias de la Naturaleza', 'BC2', 'Resolución de Problemas', 'CE-CN3', 'Aplica diversos procedimientos científicos y tecnológicos para solucionar problemas o dar respuestas a fenómenos naturales relacionados con los fundamentos de la Física.'),
('Secundaria', '6to', 'Ciencias de la Naturaleza', 'BC4', 'Ética y Ciudadana', 'CE-CN4', 'Analiza críticamente la naturaleza y filosofía de la física, ingenierías y las tecnologías, sus aportes, alcance del desarrollo tecnológico en nuestra sociedad y la ética en la investigación.'),
('Secundaria', '6to', 'Ciencias de la Naturaleza', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-CN7', 'Gestiona actitudes intelectuales, emocionales y conductuales proactivas al desarrollo de su proyección personal y profesional desde la física e ingenierías.'),
('Secundaria', '6to', 'Ciencias de la Naturaleza', 'BC3', 'Científica y Tecnológica', 'CE-CN5', 'Se cuestiona e identifica problemas y situaciones, y construye una explicación utilizando conceptos, modelos, leyes, teorías y procesos fundamentales de la Física y las ingenierías.'),
('Secundaria', '6to', 'Ciencias de la Naturaleza', 'BC3', 'Ambiental y de la Salud', 'CE-CN6', 'Asume y actúa con responsabilidad crítica y autónoma para un desarrollo sostenible, cuidado ambiental y de su salud, basadas en las ideas y teorías de la Física.'),

-- Educación Artística
('Secundaria', '6to', 'Educación Artística', 'BC1', 'Comunicativa', 'CE-EA1', 'Comunica ideas artísticamente utilizando de manera creativa signos y símbolos.'),
('Secundaria', '6to', 'Educación Artística', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-EA2', 'Crea proyectos valorando las diversas formas de comunicación artística como medio de generación de recursos y emprendimiento.'),
('Secundaria', '6to', 'Educación Artística', 'BC2', 'Resolución de Problemas', 'CE-EA3', 'Crea proyectos artísticos multidisciplinares que busquen dar respuestas a problemáticas sociales y/o personales.'),
('Secundaria', '6to', 'Educación Artística', 'BC4', 'Ética y Ciudadana', 'CE-EA4', 'Construye propuestas multidisciplinares de impacto social, que fortalezcan un sentido de identidad personal, comunitaria y que puedan significar un aporte a la cultura nacional.'),
('Secundaria', '6to', 'Educación Artística', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-EA7', 'Se descubre como parte de una comunidad, a partir de reflexiones sobre problemáticas sociales y culturales que la afectan y que reflejan en la ejecución de los proyectos y propuestas artísticas.'),
('Secundaria', '6to', 'Educación Artística', 'BC3', 'Científica y Tecnológica', 'CE-EA5', 'Realiza propuestas artísticas a partir del uso adecuado de recursos tecnológicos.'),
('Secundaria', '6to', 'Educación Artística', 'BC3', 'Ambiental y de la Salud', 'CE-EA6', 'Produce obras a partir de temáticas medioambientales, ecológicas y de salud pública, utilizando adecuadamente técnicas y lenguajes artísticos.'),

-- Educación Física
('Secundaria', '6to', 'Educación Física', 'BC1', 'Comunicativa', 'CE-EF1', 'Emplea su conocimiento amplio de su esquema corporal, para comunicar ideas y emociones en relaciones temporal-espacial en diversos entornos.'),
('Secundaria', '6to', 'Educación Física', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-EF2', 'Emprende la creación de acciones motrices innovadoras a partir de la noción de su esquema corporal, como resultante de la variación de patrones, tamaños, formas, direcciones y relaciones temporal-espacial en diversos entornos.'),
('Secundaria', '6to', 'Educación Física', 'BC2', 'Resolución de Problemas', 'CE-EF3', 'Aplica las reglas y los elementos técnicos de las diversas modalidades deportivas en situaciones táctico-estratégicas, a los fines de fortalecer el desarrollo de habilidades y destrezas técnicas que facilitan el buen desempeño de la práctica deportiva en situaciones de la vida cotidiana.'),
('Secundaria', '6to', 'Educación Física', 'BC4', 'Ética y Ciudadana', 'CE-EF4', 'Reconstruye reglas de juego en actividades motrices diversas junto con sus compañeros relaciones de cooperación y/u oposición e interactuando adecuadamente, con el fin de fortalecer el trabajo en equipo valorando las diferencias individuales.'),
('Secundaria', '6to', 'Educación Física', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-EF7', 'Aplica sus fortalezas, talentos, limitaciones y potencialidades corporales y motrices propias y las de los demás, en situaciones variables (juegos, deportes, trabajo, vida cotidiana), mostrando motivación y disponibilidad corporal para el disfrute de la actividad motriz y el juego para alcanzar el bienestar propio y colectivo.'),
('Secundaria', '6to', 'Educación Física', 'BC3', 'Científica y Tecnológica', 'CE-EF5', 'Domina su esquema corporal en la realización de diversas actividades motrices deportivas, como resultado del análisis de las normas técnicas, los implementos y condiciones del espacio donde se lleva a cabo, con el uso de los medios digitales y dispositivos tecnológicos idóneos.'),
('Secundaria', '6to', 'Educación Física', 'BC3', 'Ambiental y de la Salud', 'CE-EF6', 'Domina los cambios que percibe en su cuerpo que le permiten el incremento en su actividad motora y realizar acciones complejas, a fin de desarrollar una relación armónica, saludable y creativa con el espacio que lo rodea y con las demás personas.'),

-- Formación Integral Humana y Religiosa
('Secundaria', '6to', 'Formación Integral Humana y Religiosa', 'BC1', 'Comunicativa', 'CE-FIHR1', 'Promueve principios y valores para la vida, a partir del mensaje de Jesús de Nazaret en los evangelios y otros escritos del Nuevo Testamento, con la finalidad de fomentar relaciones armoniosas y respetuosas en diferentes contextos.'),
('Secundaria', '6to', 'Formación Integral Humana y Religiosa', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-FIHR2', 'Promueve principios y valores a partir del mensaje de Jesús de Nazaret, con la finalidad de crear conciencia sobre el respeto a la vida en sus relaciones interpersonales.'),
('Secundaria', '6to', 'Formación Integral Humana y Religiosa', 'BC2', 'Resolución de Problemas', 'CE-FIHR3', 'Fomenta valores y actitudes del cristianismo en la resolución de problemas que afectan la realización de los jóvenes, con la finalidad de desarrollar relaciones armoniosas y constructivas para la promoción personal y comunitaria.'),
('Secundaria', '6to', 'Formación Integral Humana y Religiosa', 'BC4', 'Ética y Ciudadana', 'CE-FIHR4', 'Plantea sus valores, habilidades y actitudes relacionadas al mundo laboral con la finalidad de establecer su proyecto de vida en la búsqueda de su realización personal.'),
('Secundaria', '6to', 'Formación Integral Humana y Religiosa', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-FIHR7', 'Plantea las características y valores del estilo de vida de Jesús de Nazaret, con la finalidad de tomar en cuenta sus enseñanzas en los planes y proyectos desarrollados en su vida.'),
('Secundaria', '6to', 'Formación Integral Humana y Religiosa', 'BC3', 'Científica y Tecnológica', 'CE-FIHR5', 'Desarrolla proyectos que promueven criterios éticos y valores morales en el uso de las ciencias y las tecnologías con la finalidad de proteger la vida en todas sus manifestaciones y la convivencia del ser humano en sociedad.'),
('Secundaria', '6to', 'Formación Integral Humana y Religiosa', 'BC3', 'Ambiental y de la Salud', 'CE-FIHR6', 'Fomenta iniciativas de defensa de la vida y protección del entorno natural creado por Dios para las presentes y futuras generaciones, con la finalidad de fomentar un desarrollo sostenible de la sociedad y el medioambiente natural.')
ON CONFLICT (nivel, grado, asignatura, competencia_fundamental) 
DO UPDATE SET 
    codigo = EXCLUDED.codigo,
    descriptor = EXCLUDED.descriptor,
    bloque = EXCLUDED.bloque,
    updated_at = NOW();
